const data = $input.first().json;
const posts = data?.data?.children || [];
const topPosts = posts
  .filter(p => !p.data.stickied)
  .slice(0, 10)
  .map((p, i) => {
    const d = p.data;
    return `${i+1}. [Score: ${d.score}] ${d.title} (${d.num_comments} comments)`;
  })
  .join('\n');
return { json: { redditSummary: topPosts } };

const redditRaw = $('Fetch Reddit Posts').first().json;
const redditPosts = (redditRaw?.data?.children || []).filter(p => !p.data.stickied);
const hnRaw = $input.first().json;
const hnHits = hnRaw.hits || [];

const VIRAL_KEYWORDS = ['ai ', ' ai', 'robot', 'ban', 'billion', 'trillion', 'hack', 'breach', 'leak', 'secret', 'first ', 'outrage', 'lawsuit', 'fired', 'ceo ', 'agi', 'gpt', 'claude', 'open source', 'shutdown', 'censor', 'record ', 'largest', 'biggest', 'collapse', 'surge', 'revolution', 'milestone', 'breakthrough'];

function viralBoost(title) {
  const lower = title.toLowerCase();
  return VIRAL_KEYWORDS.filter(k => lower.includes(k)).length * 300;
}

const scored = [
  ...redditPosts.map(p => ({
    source: 'Reddit',
    title: p.data.title,
    engagementScore: p.data.score + p.data.num_comments * 2 + viralBoost(p.data.title)
  })),
  ...hnHits.slice(0, 10).map(h => ({
    source: 'HN',
    title: h.title,
    engagementScore: h.points + h.num_comments * 3 + viralBoost(h.title)
  }))
].sort((a, b) => b.engagementScore - a.engagementScore).slice(0, 6);

const rankedStories = scored.map((s, i) =>
  `${i+1}. [${s.source} | Score: ${s.engagementScore}] ${s.title}`
).join('\n');

return {
  json: { rankedStories }
};

const data = $input.first().json;
const keys = JSON.parse(require('fs').readFileSync('/home/node/keys.json', 'utf8'));
return {
  json: {
    rawStory: data.rankedStories,
    timestamp: new Date().toISOString(),
    geminiApiKey: keys.geminiApiKey
  }
};

const geminiResponse = $input.first().json;
let response = '';
try {
  response = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Could not extract text from Gemini response: ' + JSON.stringify(geminiResponse).substring(0, 300));
}
let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) { parsed = JSON.parse(jsonMatch[0]); }
  else throw new Error('Could not parse script JSON: ' + response.substring(0, 200));
}
function findScriptData(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.SCRIPT || obj.script) return obj;
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    if (val && typeof val === 'object' && !Array.isArray(val)) {
      if (val.SCRIPT || val.script) return val;
    }
  }
  return null;
}
let data = findScriptData(parsed);
if (!data) throw new Error('Could not find SCRIPT in response. Keys: ' + JSON.stringify(Object.keys(parsed)));
const script = data.SCRIPT || data.script;
const title = data.TITLE || data.title;
const description = data.DESCRIPTION || data.description || '';
const tags = data.TAGS || data.tags || [];
const imagePrompts = data.IMAGE_PROMPTS || data.image_prompts || data.imagePrompts || [];
if (!script) throw new Error('SCRIPT field is empty');
if (!title) throw new Error('TITLE field is empty');
if (!Array.isArray(imagePrompts) || imagePrompts.length < 5) {
  throw new Error('Need at least 5 image prompts, got ' + (Array.isArray(imagePrompts) ? imagePrompts.length : 'non-array'));
}
const wordCount = script.split(/\s+/).length;
if (wordCount < 80) {
  throw new Error('Script too short: ' + wordCount + ' words (need 80+). Retry should fix this.');
}
if (!Array.isArray(tags) || tags.length < 3) {
  throw new Error('Need at least 3 tags, got ' + (Array.isArray(tags) ? tags.length : 'non-array'));
}
return {
  json: {
    script,
    title,
    description,
    tags: Array.isArray(tags) ? tags : [],
    imagePrompts,
    wordCount,
    timestamp: new Date().toISOString()
  }
};

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const scriptData = $input.first().json;
const prompts = scriptData.imagePrompts || [];
if (prompts.length === 0) throw new Error('No image prompts found');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const apiKey = keys.falApiKey;
if (!apiKey || apiKey === 'YOUR_FAL_API_KEY') throw new Error('falApiKey not set in keys.json');

const tmpDir = '/tmp/n8n_falimg_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const config = { prompts, apiKey };
  fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

  const js = [
    "const https = require('https');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
    "const {prompts, apiKey} = cfg;",
    "function post(urlStr, body) {",
    "  return new Promise((res, rej) => {",
    "    const u = new URL(urlStr);",
    "    const b = JSON.stringify(body);",
    "    const r = https.request({",
    "      hostname: u.hostname, path: u.pathname+u.search, method: 'POST',",
    "      headers: {'Content-Type':'application/json','Content-Length':Buffer.byteLength(b),'Authorization':'Key '+apiKey}",
    "    }, resp => {",
    "      const c=[]; resp.on('data',d=>c.push(d)); resp.on('end',()=>res({s:resp.statusCode,b:Buffer.concat(c).toString()}));",
    "    });",
    "    r.on('error',rej); r.write(b); r.end();",
    "  });",
    "}",
    "async function main() {",
    "  const urls = [];",
    "  for (let i=0; i<prompts.length; i++) {",
    "    process.stderr.write('Image '+(i+1)+'/'+prompts.length+'\\n');",
    "    const prompt = 'cinematic portrait 9:16 vertical composition, ' + prompts[i];",
    "    const r = await post('https://fal.run/fal-ai/flux/schnell', {prompt, image_size:{width:768,height:1344}, num_images:1, enable_safety_checker:false});",
    "    if (r.s !== 200) throw new Error('fal.ai error '+r.s+': '+r.b.substring(0,300));",
    "    const url = JSON.parse(r.b).images[0].url;",
    "    urls.push(url);",
    "    process.stderr.write('  OK: '+url.substring(0,80)+'\\n');",
    "  }",
    "  process.stdout.write(JSON.stringify({imageUrls:urls}));",
    "}",
    "main().catch(e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});"
  ];
  fs.writeFileSync(path.join(tmpDir, 'run.js'), js.join('\n'));

  const out = await new Promise((resolve, reject) => {
    exec('node "' + path.join(tmpDir, 'run.js') + '" "' + tmpDir + '"',
      { timeout: 300000, maxBuffer: 10*1024*1024 },
      (err, stdout, stderr) => {
        if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
        else resolve(stdout);
      });
  });

  const result = JSON.parse(out);
  return {
    json: {
      imageUrls: result.imageUrls,
      imageCount: result.imageUrls.length,
      script: scriptData.script,
      title: scriptData.title,
      description: scriptData.description,
      tags: scriptData.tags,
      imagePrompts: scriptData.imagePrompts
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const imgData = $input.first().json;
const imageUrls = imgData.imageUrls || [];
if (imageUrls.length === 0) throw new Error('No image URLs from Generate Images');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const apiKey = keys.falApiKey;
if (!apiKey || apiKey === 'YOUR_FAL_API_KEY') throw new Error('falApiKey not set in keys.json');

// Motion prompts for each clip (cycled)
const motions = [
  'slow cinematic zoom in, subtle atmospheric depth, particles floating',
  'gentle camera pan left to right, soft bokeh, cinematic color grade',
  'smooth dolly push forward, dramatic shadows shifting, epic scale',
  'slow zoom out revealing scene, ambient light rays, moody atmosphere',
  'camera orbit around subject, particle effects, cinematic depth of field',
  'gentle upward tilt, dramatic sky, sweeping cinematic movement'
];

const KLING_MODEL = 'fal-ai/kling-video/v1.6/standard/image-to-video';
const tmpDir = '/tmp/n8n_kling_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const config = {
    imageUrls,
    motions,
    model: KLING_MODEL,
    apiKey,
    clipDuration: '5'
  };
  fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

  const js = [
    "const https = require('https');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
    "const {imageUrls, motions, model, apiKey, clipDuration} = cfg;",
    "const BASE = 'queue.fal.run';",
    "const sleep = ms => new Promise(r=>setTimeout(r,ms));",
    "",
    "function apiReq(method, path, body) {",
    "  return new Promise((res, rej) => {",
    "    const b = body ? JSON.stringify(body) : null;",
    "    const headers = {'Authorization':'Key '+apiKey};",
    "    if (b) { headers['Content-Type']='application/json'; headers['Content-Length']=Buffer.byteLength(b); }",
    "    const r = https.request({hostname:BASE, path, method, headers}, resp => {",
    "      const c=[]; resp.on('data',d=>c.push(d)); resp.on('end',()=>res({s:resp.statusCode,b:Buffer.concat(c).toString()}));",
    "    });",
    "    r.on('error',rej); if(b) r.write(b); r.end();",
    "  });",
    "}",
    "",
    "async function submitKling(imageUrl, prompt) {",
    "  const r = await apiReq('POST', '/'+model, {image_url:imageUrl, prompt, duration:clipDuration, aspect_ratio:'9:16'});",
    "  if (r.s !== 200) throw new Error('Kling submit error '+r.s+': '+r.b.substring(0,300));",
    "  return JSON.parse(r.b).request_id;",
    "}",
    "",
    "async function pollKling(requestId, timeoutMs) {",
    "  const start = Date.now();",
    "  while (Date.now()-start < timeoutMs) {",
    "    await sleep(8000);",
    "    const r = await apiReq('GET', '/'+model+'/requests/'+requestId+'/status', null);",
    "    if (r.s !== 200) { await sleep(5000); continue; }",
    "    const data = JSON.parse(r.b);",
    "    const status = data.status || (data.queue_position !== undefined ? 'IN_QUEUE' : '');",
    "    process.stderr.write('  Status: '+status+'\\n');",
    "    if (status === 'COMPLETED') {",
    "      const res = await apiReq('GET', '/'+model+'/requests/'+requestId, null);",
    "      const resData = JSON.parse(res.b);",
    "      return resData.video.url;",
    "    }",
    "    if (status === 'FAILED') throw new Error('Kling generation failed for '+requestId);",
    "  }",
    "  throw new Error('Kling timeout after '+(timeoutMs/1000)+'s for '+requestId);",
    "}",
    "",
    "async function main() {",
    "  const videoUrls = [];",
    "  const clipDurations = [];",
    "  for (let i=0; i<imageUrls.length; i++) {",
    "    process.stderr.write('Clip '+(i+1)+'/'+imageUrls.length+'\\n');",
    "    const motion = motions[i % motions.length];",
    "    const requestId = await submitKling(imageUrls[i], motion);",
    "    process.stderr.write('  Submitted: '+requestId.substring(0,16)+'...\\n');",
    "    const videoUrl = await pollKling(requestId, 1200000);",
    "    videoUrls.push(videoUrl);",
    "    clipDurations.push(5.0);",
    "    process.stderr.write('  Done: '+videoUrl.substring(0,80)+'\\n');",
    "  }",
    "  process.stdout.write(JSON.stringify({videoUrls, clipDurations}));",
    "}",
    "main().catch(e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});"
  ];
  fs.writeFileSync(path.join(tmpDir, 'run.js'), js.join('\n'));

  const out = await new Promise((resolve, reject) => {
    exec('node "' + path.join(tmpDir, 'run.js') + '" "' + tmpDir + '"',
      { timeout: 7800000, maxBuffer: 10*1024*1024 },
      (err, stdout, stderr) => {
        if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
        else resolve(stdout);
      });
  });

  const result = JSON.parse(out);
  return {
    json: {
      videoUrls: result.videoUrls,
      clipDurations: result.clipDurations,
      clipCount: result.videoUrls.length,
      script: imgData.script,
      title: imgData.title,
      description: imgData.description,
      tags: imgData.tags
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

