const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const inputItem = $input.first();
const voiceBinary = inputItem.binary && inputItem.binary.voice;
if (!voiceBinary) throw new Error('No voice binary from ElevenLabs node');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const apiKey = keys.stabilityApiKey;

const tmpDir = '/tmp/n8n_music_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  let musicBase64;

  if (!apiKey || apiKey === 'YOUR_STABILITY_API_KEY') {
    // Fallback: generate silence so pipeline continues without music
    const { execSync } = require('child_process');
    const silencePath = path.join(tmpDir, 'music.mp3');
    execSync('ffmpeg -y -f lavfi -i anullsrc=r=44100:cl=stereo -t 45 -c:a libmp3lame -b:a 128k "' + silencePath + '"', { timeout: 30000 });
    musicBase64 = fs.readFileSync(silencePath).toString('base64');
  } else {
    const config = { apiKey };
    fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

    const js = [
      "const https = require('https');",
      "const fs = require('fs');",
      "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
      "const boundary = '----n8nbnd'+Date.now();",
      "const parts = [",
      "  '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"prompt\"\\r\\n\\r\\nupbeat energetic electronic background music for tech news, modern synthesizer 120bpm, no lyrics, background track',",
      "  '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"output_format\"\\r\\n\\r\\nmp3',",
      "  '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"duration\"\\r\\n\\r\\n45',",
      "  '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"model\"\\r\\n\\r\\nstable-audio-2.5',",
      "  '--'+boundary+'--'",
      "].join('\\r\\n');",
      "const body = Buffer.from(parts);",
      "const req = https.request({",
      "  hostname: 'api.stability.ai',",
      "  path: '/v2beta/stable-audio/generate',",
      "  method: 'POST',",
      "  headers: {",
      "    'Authorization': 'Bearer '+cfg.apiKey,",
      "    'Accept': 'audio/*',",
      "    'Content-Type': 'multipart/form-data; boundary='+boundary,",
      "    'Content-Length': body.length",
      "  }",
      "}, res => {",
      "  if (res.statusCode !== 200) {",
      "    const c=[]; res.on('data',d=>c.push(d)); res.on('end',()=>{ process.stderr.write('FATAL: Stability API '+res.statusCode+': '+Buffer.concat(c).toString().substring(0,300)+'\\n'); process.exit(1); });",
      "    return;",
      "  }",
      "  const f = require('fs').createWriteStream(process.argv[2]+'/music.mp3');",
      "  res.pipe(f);",
      "  f.on('finish',()=>process.stdout.write(JSON.stringify({ok:true})));",
      "  f.on('error',e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});",
      "});",
      "req.on('error',e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});",
      "req.write(body); req.end();"
    ];
    fs.writeFileSync(path.join(tmpDir, 'music.js'), js.join('\n'));

    await new Promise((resolve, reject) => {
      exec('node "' + path.join(tmpDir, 'music.js') + '" "' + tmpDir + '"',
        { timeout: 120000, maxBuffer: 50*1024*1024 },
        (err, stdout, stderr) => {
          if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
          else resolve();
        });
    });
    musicBase64 = fs.readFileSync(path.join(tmpDir, 'music.mp3')).toString('base64');
  }

  return {
    json: { ...inputItem.json },
    binary: {
      voice: voiceBinary,
      music: { data: musicBase64, mimeType: 'audio/mpeg', fileName: 'bgmusic.mp3' }
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

const { exec, execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const videoData = $('Generate Video Clips (fal.ai Kling)').first().json;
const videoUrls = videoData.videoUrls || [];
const clipDurations = videoData.clipDurations || [];
const numClips = videoUrls.length;
if (numClips === 0) throw new Error('No video URLs from Kling');

const inputBinary = $input.first().binary;
if (!inputBinary || !inputBinary.voice) throw new Error('No voice binary');
if (!inputBinary.music) throw new Error('No music binary');

const scriptText = $('Parse Script JSON').first().json.script || '';

const tmpDir = '/tmp/n8n_compose_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  // Save audio files
  const voicePath = path.join(tmpDir, 'voice.mp3');
  const musicPath = path.join(tmpDir, 'music.mp3');
  fs.writeFileSync(voicePath, Buffer.from(inputBinary.voice.data, 'base64'));
  fs.writeFileSync(musicPath, Buffer.from(inputBinary.music.data, 'base64'));

  // Get voice duration
  let audioDuration = 35;
  try {
    const info = execSync('ffmpeg -i "' + voicePath + '" 2>&1 || true', { timeout: 10000 }).toString();
    const m = info.match(/Duration: (\d+):(\d+):([\d.]+)/);
    if (m) audioDuration = parseInt(m[1])*3600 + parseInt(m[2])*60 + parseFloat(m[3]);
  } catch(e) {}

  // Download video clips via sandbox-escaped node (https module)
  const dlCfg = { urls: videoUrls, tmpDir };
  fs.writeFileSync(path.join(tmpDir, 'dl_cfg.json'), JSON.stringify(dlCfg));
  const dlJs = [
    "const https = require('https');",
    "const http = require('http');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/dl_cfg.json','utf8'));",
    "const {urls, tmpDir} = cfg;",
    "function dl(url, dest, redirect) {",
    "  return new Promise((res, rej) => {",
    "    const mod = url.startsWith('https') ? https : http;",
    "    const f = fs.createWriteStream(dest);",
    "    mod.get(url, r => {",
    "      if ((r.statusCode===301||r.statusCode===302) && r.headers.location && !redirect) {",
    "        f.close(); return dl(r.headers.location, dest, true).then(res).catch(rej);",
    "      }",
    "      r.pipe(f);",
    "      f.on('finish', ()=>f.close(res));",
    "      f.on('error', rej);",
    "    }).on('error', rej);",
    "  });",
    "}",
    "async function main() {",
    "  for (let i=0; i<urls.length; i++) {",
    "    await dl(urls[i], tmpDir+'/clip_'+i+'.mp4', false);",
    "    process.stderr.write('Downloaded clip '+(i+1)+'/'+urls.length+'\\n');",
    "  }",
    "  process.stdout.write('ok');",
    "}",
    "main().catch(e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});"
  ].join('\n');
  fs.writeFileSync(path.join(tmpDir, 'dl.js'), dlJs);
  await new Promise((res, rej) => {
    exec('node "' + path.join(tmpDir, 'dl.js') + '" "' + tmpDir + '"',
      { timeout: 180000, maxBuffer: 10*1024*1024 },
      (err, stdout, stderr) => {
        if (err) rej(new Error('Clip download failed: ' + (stderr||err.message)));
        else res();
      });
  });

  const clipPaths = Array.from({length: numClips}, (_, i) => path.join(tmpDir, 'clip_'+i+'.mp4'));

  // Build SRT captions
  const words = scriptText.split(/\s+/).filter(w => w.length > 0);
  const fadeDur = 0.3;
  const targetClipDur = (audioDuration + (numClips-1)*fadeDur) / numClips;
  const wordsPerSeg = Math.ceil(words.length / numClips);
  const fmt = s => {
    const h = Math.floor(s/3600), min = Math.floor((s%3600)/60), sec = (s%60).toFixed(3).replace('.', ',');
    return String(h).padStart(2,'0')+':'+String(min).padStart(2,'0')+':'+sec;
  };
  let srt = '';
  for (let i=0; i<numClips; i++) {
    const t0 = i*(targetClipDur-fadeDur);
    const t1 = t0 + targetClipDur - 0.3;
    const seg = words.slice(i*wordsPerSeg, (i+1)*wordsPerSeg).join(' ');
    srt += (i+1)+'\n'+fmt(t0)+' --> '+fmt(t1)+'\n'+seg+'\n\n';
  }
  const srtPath = path.join(tmpDir, 'captions.srt');
  fs.writeFileSync(srtPath, srt);

  // Pass 1: process each clip (upscale, enhance, minterpolate, stretch)
  const procPaths = [];
  for (let i=0; i<numClips; i++) {
    const origDur = clipDurations[i] || 5.0;
    const speed = origDur / targetClipDur;
    const procPath = path.join(tmpDir, 'proc_'+i+'.mp4');
    const vf = [
      'scale=1080:1920:force_original_aspect_ratio=increase:flags=lanczos',
      'crop=1080:1920',
      'unsharp=luma_msize_x=3:luma_msize_y=3:luma_amount=0.8',
      'eq=contrast=1.02:saturation=1.1',
      'minterpolate=fps=60:mi_mode=mci:mc_mode=aobmc:me_mode=bidir:vsbmc=1',
      'setpts=PTS/'+speed.toFixed(4),
      'trim=duration='+(targetClipDur+0.05).toFixed(2),
      'setpts=PTS-STARTPTS',
      'fps=30'
    ].join(',');
    execSync('ffmpeg -y -i "'+clipPaths[i]+'" -vf "'+vf+'" -c:v libx264 -preset fast -crf 18 -pix_fmt yuv420p "'+procPath+'"',
      { maxBuffer: 100*1024*1024, timeout: 300000 });
    procPaths.push(procPath);
  }

  // Mix voice + music at 28% volume
  const mixedPath = path.join(tmpDir, 'mixed.aac');
  execSync(
    'ffmpeg -y -i "'+voicePath+'" -i "'+musicPath+'" -filter_complex "[0:a]volume=1.0[v];[1:a]volume=0.28,atrim=duration='+audioDuration.toFixed(2)+'[m];[v][m]amix=inputs=2:duration=first:normalize=0[out]" -map "[out]" -c:a aac -b:a 192k "'+mixedPath+'"',
    { timeout: 60000, maxBuffer: 50*1024*1024 }
  );

  // Pass 2: xfade stitch
  const inArgs = procPaths.map(p=>'-i "'+p+'"').join(' ') + ' -i "'+mixedPath+'"';
  const xfadeParts = [];
  let lastLbl = '0:v', offset = targetClipDur - fadeDur;
  for (let i=1; i<numClips; i++) {
    const outLbl = i < numClips-1 ? 't'+i : 'vout';
    xfadeParts.push('['+lastLbl+']['+i+':v]xfade=transition=fade:duration='+fadeDur+':offset='+offset.toFixed(2)+'['+outLbl+']');
    lastLbl = outLbl;
    offset += targetClipDur - fadeDur;
  }

  const forceStyle = 'FontSize=52,PrimaryColour=&Hffffff,OutlineColour=&H000000,BorderStyle=3,Outline=2,Shadow=1,Alignment=2,MarginV=100';
  const srtFilter = '[vout]subtitles=' + srtPath + ':force_style=' + forceStyle + '[vfinal]';
  const filterComplex = xfadeParts.join('; ') + ';' + srtFilter;

  const outputPath = path.join(tmpDir, 'output.mp4');
  const cmd = 'ffmpeg ' + inArgs + ' -filter_complex "' + filterComplex + '" -map "[vfinal]" -map ' + numClips + ':a -c:v libx264 -preset slow -crf 18 -pix_fmt yuv420p -c:a copy -shortest -y "' + outputPath + '"';
  execSync(cmd, { maxBuffer: 500*1024*1024, timeout: 600000 });

  const videoBuf = fs.readFileSync(outputPath);
  return {
    json: {
      videoGenerated: true,
      duration: audioDuration,
      numClips,
      targetClipDuration: targetClipDur,
      title: videoData.title,
      description: videoData.description,
      tags: videoData.tags,
      script: scriptText
    },
    binary: {
      video: { data: videoBuf.toString('base64'), mimeType: 'video/mp4', fileName: 'youtube_short.mp4' }
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

